import { defineComponent, h, type PropType } from 'vue';
import { cardStyleKeys } from '../lib/core';
import type { CardElement } from '../lib/core';
import styles from './card.module.scss';

export const Card = defineComponent({
	name: 'Card',
	props: {
		as: {
			type: String as PropType<CardElement>,
			default: 'div',
		},
	},
	setup(props, { slots, attrs }) {
		return () => h(props.as!, { ...attrs, class: [styles[cardStyleKeys.card], attrs.class] }, slots.default?.());
	},
});

export const CardHeader = defineComponent({
	name: 'CardHeader',
	setup(_, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[cardStyleKeys.header], attrs.class] }, slots.default?.());
	},
});

export const CardTitle = defineComponent({
	name: 'CardTitle',
	setup(_, { slots, attrs }) {
		return () => h('h3', { ...attrs, class: [styles[cardStyleKeys.title], attrs.class] }, slots.default?.());
	},
});

export const CardDescription = defineComponent({
	name: 'CardDescription',
	setup(_, { slots, attrs }) {
		return () => h('p', { ...attrs, class: [styles[cardStyleKeys.description], attrs.class] }, slots.default?.());
	},
});

export const CardAction = defineComponent({
	name: 'CardAction',
	setup(_, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[cardStyleKeys.action], attrs.class] }, slots.default?.());
	},
});

export const CardContent = defineComponent({
	name: 'CardContent',
	setup(_, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[cardStyleKeys.content], attrs.class] }, slots.default?.());
	},
});

export const CardFooter = defineComponent({
	name: 'CardFooter',
	setup(_, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[cardStyleKeys.footer], attrs.class] }, slots.default?.());
	},
});

export default Card;

@use '../../../styles/variables/colors' as *;

.card {
	display: flex;
	flex-direction: column;
	gap: var(--tile-card-gap, $spacing-4);
	border-radius: var(--tile-card-radius, $radius-lg);
	border: 1px solid var(--tile-card-border, $border);
	background-color: var(--tile-card-background, $background);
	color: $foreground;
	box-shadow: var(--tile-card-shadow, $shadow);
	overflow: hidden;
	transition: box-shadow $transition-normal;

	&:hover {
		box-shadow: var(--tile-card-hover-shadow, $shadow-md);
	}
}

.cardHeader {
	display: grid;
	grid-template-columns: 1fr;
	grid-auto-rows: min-content;
	align-items: start;
	gap: $spacing-1;
	padding: var(--tile-card-header-padding, $spacing-6 $spacing-6 0);

	// 存在操作区时启用右侧列
	&:has(.cardAction) {
		grid-template-columns: 1fr auto;
	}
}

.cardTitle {
	font-size: var(--tile-card-title-size, $text-xl);
	font-weight: var(--tile-card-title-weight, $font-semibold);
	line-height: var(--tile-card-title-leading, $leading-tight);
	color: $foreground;
	margin: 0;
}

.cardDescription {
	font-size: $text-sm;
	color: var(--tile-card-description-color, $muted-foreground);
	line-height: $leading-normal;
	margin: 0;
}

.cardAction {
	grid-column-start: 2;
	grid-row-start: 1;
	grid-row-end: span 2;
	align-self: start;
	justify-self: end;
}

.cardContent {
	padding: var(--tile-card-content-padding, 0 $spacing-6);
}

.cardFooter {
	display: flex;
	align-items: center;
	gap: $spacing-4;
	padding: var(--tile-card-footer-padding, 0 $spacing-6 $spacing-6);
}
